<?php declare(strict_types=1);
namespace DoubleYoupi\Core;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Shared installation / migration tasks — SOLO VERSION.
 *
 * Called by Activator::activate() (on activation) AND by
 * Plugin::maybe_run_migrations() (on each version upgrade). Idempotent:
 * options are only written when absent, and activation callbacks
 * (taxonomy registration, etc.) are safe to replay.
 *
 * All content specific to the bundled module comes from SoloConfig
 * (generated by the build) — this file remains 100% generic.
 */
final class Installer {

	public static function run(): void {
		foreach ( SoloConfig::option_defaults() as $key => $value ) {
			if ( get_option( $key, null ) === null ) {
				add_option( $key, $value );
			}
		}

		foreach ( SoloConfig::activation_callbacks() as $callback ) {
			if ( is_callable( $callback ) ) {
				call_user_func( $callback );
			}
		}

		// Required when a callback registers a taxonomy with show_in_rest=true.
		flush_rewrite_rules();
	}
}
